    {"id":"famotidine_injectable","name":"Famotidine Injectable","name_ja":"ファモチジン注射","category":"gastrointestinal","mechanism":"H2 receptor antagonist; reduces gastric acid secretion (parenteral for NPO patients)","mechanism_ja":"H2受容体拮抗薬。胃酸分泌抑制（絶食中の非経口投与）","species_info":{"dog":{"dose":"0.5-1 mg/kg IV q12h","notes_ja":"絶食中の消化管潰瘍予防・急性嘔吐時","notes":"GI ulcer prevention in NPO patients, acute vomiting"},"cat":{"dose":"0.5-1 mg/kg IV q12-24h","notes_ja":"絶食中の消化管保護","notes":"GI protection in NPO patients"},"ferret":{"dose":"0.5 mg/kg IV/SC q12h","notes_ja":"ヘリコバクター性胃炎","notes":"Helicobacter gastritis"}},"side_effects":"Bradycardia (rapid IV), pain on injection","side_effects_ja":"徐脈（急速IV）、注射時疼痛","contraindications":"None significant; adjust in renal failure","contraindications_ja":"特になし。腎不全では用量調整","drug_interactions":[]},
    {"id":"omeprazole_injectable","name":"Omeprazole Injectable","name_ja":"オメプラゾール注射","category":"gastrointestinal","mechanism":"Proton pump inhibitor; irreversibly blocks H+/K+-ATPase in parietal cells (parenteral)","mechanism_ja":"プロトンポンプ阻害薬。壁細胞のH+/K+-ATPaseを不可逆的に阻害（非経口）","species_info":{"dog":{"dose":"1 mg/kg IV q24h","notes_ja":"重症消化管潰瘍・出血性胃炎（経口不可時）","notes":"Severe GI ulceration, hemorrhagic gastritis (when oral impossible)"},"cat":{"dose":"1 mg/kg IV q24h","notes_ja":"重症消化管潰瘍","notes":"Severe GI ulceration"},"horse":{"dose":"1 mg/kg IV q24h","notes_ja":"重症胃潰瘍（経口不可時）","notes":"Severe gastric ulcer (when oral impossible)"}},"side_effects":"Phlebitis, GI upset","side_effects_ja":"静脈炎、消化器症状","contraindications":"None significant","contraindications_ja":"特になし","drug_interactions":[{"drug":"ketoconazole","severity":"moderate","description_ja":"ケトコナゾール吸収低下（胃酸低下）","description":"Decreased ketoconazole absorption (reduced gastric acid)"}]},
